css:
.cross-training-page {
  max-width: 1120px;
  margin: 0 auto;
  padding: 4rem 2rem 5rem;
  font-family: inherit;
  background: #fff;
}

.page-hero {
  margin-bottom: 3rem;
}

.page-label {
  display: inline-block;
  margin-bottom: 1rem;
  padding: 5px 12px;
  border: 1px solid #B9D7F3;
  border-radius: 999px;
  background: #E6F1FB;
  color: #174B8A;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.03em;
}

.page-title {
  margin: 0 0 0.75rem;
  color: #111;
  font-size: 42px;
  font-weight: 700;
  letter-spacing: -0.04em;
  line-height: 1.2;
}

.page-subtitle {
  margin: 0;
  color: #777;
  font-size: 16px;
  line-height: 1.6;
}

.year-block {
  margin-bottom: 2.75rem;
}

.year-block.current-year {
  margin-bottom: 3rem;
  padding: 1.5rem 1.5rem 1.75rem;
  border: 1px solid #E1E8F5;
  border-radius: 22px;
  background: linear-gradient(180deg, #F5F8FF 0%, #FFFFFF 100%);
}

.year-header {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-bottom: 1.5rem;
}

.year-label {
  color: #111;
  font-size: 28px;
  font-weight: 500;
  line-height: 1;
}

.current-year .year-label {
  color: #174B8A;
  font-weight: 700;
  letter-spacing: 0.08em;
}

.year-count {
  padding: 2px 10px;
  border: 0.5px solid #e5e5e5;
  border-radius: 99px;
  background: #f5f5f5;
  color: #aaa;
  font-size: 12px;
}

.current-year .year-count {
  border-color: #C9D9EE;
  background: #fff;
  color: #174B8A;
}

.year-line {
  flex: 1;
  border-top: 0.5px solid #e0e0e0;
}

.current-year .year-line {
  border-top-color: #C9D9EE;
}

.items {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.item {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 170px;
  align-items: start;
  gap: 20px;
  padding: 1.25rem 1.5rem;
  border: 1px solid #E3E5E8;
  border-radius: 13px;
  background: #FAFBFC;
}

.item-current {
  border-color: #D8E2F0;
  background: #fff;
  box-shadow: 0 8px 20px rgba(23, 75, 138, 0.06);
}

.item-title {
  margin: 0 0 8px;
  color: #111;
  font-size: 16px;
  font-weight: 600;
  letter-spacing: -0.02em;
  line-height: 1.45;
}

.current-year .item-title {
  color: #0F2340;
}

.item-desc {
  margin: 0;
  color: #818892;
  font-size: 14px;
  line-height: 1.6;
  word-break: keep-all;
}

.item-meta {
  display: flex;
  min-width: 0;
  flex-direction: column;
  align-items: flex-end;
  gap: 7px;
  text-align: right;
}

.item-org {
  margin: 0;
  color: #707783;
  font-size: 13px;
  line-height: 1.4;
  white-space: nowrap;
}

.item-date {
  margin: 0;
  color: #9299A3;
  font-size: 13px;
  line-height: 1.4;
  white-space: nowrap;
}

.badge {
  display: inline-block;
  padding: 4px 10px;
  border-radius: 99px;
  font-size: 12px;
  line-height: 1;
  white-space: nowrap;
}

.badge-done {
  border: 0.5px solid #dcdcdc;
  background: #f5f5f5;
  color: #777;
}

.badge-ongoing {
  border: 0.5px solid #B5D4F4;
  background: #E6F1FB;
  color: #185FA5;
}

.badge-upcoming {
  border: 0.5px solid #C0DD97;
  background: #EAF3DE;
  color: #3B6D11;
}

@media (max-width: 768px) {
  .cross-training-page {
    padding: 3rem 1rem 4rem;
  }

  .page-title {
    font-size: 34px;
  }

  .year-block.current-year {
    padding: 1.25rem 1rem;
    border-radius: 18px;
  }

  .year-header {
    gap: 10px;
  }

  .year-label {
    font-size: 24px;
  }

  .item {
    grid-template-columns: 1fr;
    padding: 1.1rem 1.2rem;
  }

  .item-meta {
    align-items: flex-start;
    text-align: left;
  }

  .item-org,
  .item-date {
    white-space: normal;
  }
}
